use objc2::{ClassType, rc::Retained, runtime::ProtocolObject};
use objc2_app_kit::{
    NSPasteboard, NSPasteboardTypeHTML, NSPasteboardTypeString, NSPasteboardTypeTIFF,
    NSPasteboardWriting,
};
use objc2_foundation::{NSArray, NSData, NSString, NSURL};

const PRIVATE_TYPES: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

#[derive(Debug, Clone, PartialEq)]
pub enum NativeClipboardContent {
    Text { text: String, html: Option<String> },
    Html(String),
    Files(Vec<String>),
    ImageByte(Vec<u8>),
    Unknown,
}

pub fn is_private(pasteboard: &NSPasteboard) -> bool {
    let Some(types) = pasteboard.types() else {
        return false;
    };

    types
        .iter()
        .any(|kind| PRIVATE_TYPES.contains(&kind.to_string().as_str()))
}

pub fn write(pasteboard: &NSPasteboard, content: &NativeClipboardContent) {
    if matches!(content, NativeClipboardContent::Unknown) {
        return;
    }

    unsafe {
        pasteboard.clearContents();

        match content {
            NativeClipboardContent::Text { text, html } => {
                pasteboard.setString_forType(&NSString::from_str(text), NSPasteboardTypeString);

                if let Some(html) = html {
                    pasteboard.setString_forType(&NSString::from_str(html), NSPasteboardTypeHTML);
                }
            }
            NativeClipboardContent::Html(html) => {
                pasteboard.setString_forType(&NSString::from_str(html), NSPasteboardTypeHTML);
            }
            NativeClipboardContent::Files(paths) => {
                let urls: Vec<Retained<ProtocolObject<dyn NSPasteboardWriting>>> = paths
                    .iter()
                    .map(|path| {
                        ProtocolObject::from_retained(NSURL::fileURLWithPath(&NSString::from_str(
                            path,
                        )))
                    })
                    .collect();

                pasteboard.writeObjects(&NSArray::from_retained_slice(&urls));
            }
            NativeClipboardContent::ImageByte(bytes) => {
                pasteboard.setData_forType(Some(&NSData::with_bytes(bytes)), NSPasteboardTypeTIFF);
            }
            NativeClipboardContent::Unknown => {}
        }
    }
}

pub fn fetch(pasteboard: &NSPasteboard) -> NativeClipboardContent {
    unsafe {
        if let Some(objects) =
            pasteboard.readObjectsForClasses_options(&NSArray::from_slice(&[NSURL::class()]), None)
        {
            let mut file_paths = Vec::new();

            for obj in objects.iter() {
                if let Ok(url) = obj.downcast::<NSURL>()
                    && url.isFileURL()
                    && let Some(path) = url.path()
                {
                    let path = path.to_string();

                    if !path.is_empty() {
                        file_paths.push(path);
                    }
                }
            }

            if !file_paths.is_empty() {
                return NativeClipboardContent::Files(file_paths);
            }
        }

        let html = pasteboard
            .stringForType(NSPasteboardTypeHTML)
            .map(|html| html.to_string())
            .filter(|html| !html.trim().is_empty());

        if let Some(text) = pasteboard.stringForType(NSPasteboardTypeString) {
            let text = text.to_string();

            if !text.trim().is_empty() {
                return NativeClipboardContent::Text { text, html };
            }
        }

        if let Some(html) = html {
            return NativeClipboardContent::Html(html);
        }

        if let Some(data) = pasteboard.dataForType(NSPasteboardTypeTIFF) {
            let bytes = data.as_bytes_unchecked().to_vec();

            if !bytes.is_empty() {
                return NativeClipboardContent::ImageByte(bytes);
            }
        }
    }

    NativeClipboardContent::Unknown
}
